const COLORS = {
  bg: "#1B1714",
  panel: "#241E19",
  panelAlt: "#2A231D",
  line: "#3A322A",
  ink: "#ECE4D6",
  inkDim: "#B3A896",
  inkFaint: "#7A6F60",
  blood: "#A5342A",
  brass: "#B4924F",
};

const ARCH_COLORS = {
  0: "#C77B4A", // Rising Destroyer - ember orange
  1: "#5C7A8C", // Iron Veteran - steel blue
  2: "#B4924F", // Compact Finisher - brass
  3: "#6F8B6A", // Technician - sage green
  4: "#8C5C6E", // Long-Range Operator - wine
};

const DNA_AXES = [
  { key: "power", label: "Power" },
  { key: "technique", label: "Technique" },
  { key: "volume", label: "Volume" },
  { key: "longevity", label: "Longevity" },
  { key: "reach", label: "Reach" },
  { key: "win_rate", label: "Win rate" },
];

function polarPoint(cx, cy, r, angleDeg) {
  const a = ((angleDeg - 90) * Math.PI) / 180;
  return [cx + r * Math.cos(a), cy + r * Math.sin(a)];
}

function DnaRadar({ fighter, size = 260, color }) {
  const cx = size / 2;
  const cy = size / 2;
  const maxR = size * 0.36;
  const n = DNA_AXES.length;
  const rings = [0.25, 0.5, 0.75, 1];

  const dataPoints = DNA_AXES.map((axis, i) => {
    const val = fighter.dna[axis.key] / 100;
    const angle = (360 / n) * i;
    return polarPoint(cx, cy, maxR * val, angle);
  });
  const polyPath = dataPoints.map((p) => p.join(",")).join(" ");

  return (
    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`}>
      {rings.map((r, ri) => {
        const pts = DNA_AXES.map((_, i) => polarPoint(cx, cy, maxR * r, (360 / n) * i).join(",")).join(" ");
        return (
          <polygon
            key={ri}
            points={pts}
            fill="none"
            stroke={COLORS.line}
            strokeWidth={ri === rings.length - 1 ? 1.2 : 0.7}
          />
        );
      })}
      {DNA_AXES.map((_, i) => {
        const [x, y] = polarPoint(cx, cy, maxR, (360 / n) * i);
        return <line key={i} x1={cx} y1={cy} x2={x} y2={y} stroke={COLORS.line} strokeWidth={0.7} />;
      })}
      <polygon points={polyPath} fill={color} fillOpacity={0.28} stroke={color} strokeWidth={2} />
      {dataPoints.map((p, i) => (
        <circle key={i} cx={p[0]} cy={p[1]} r={2.6} fill={color} />
      ))}
      {DNA_AXES.map((axis, i) => {
        const [x, y] = polarPoint(cx, cy, maxR + 22, (360 / n) * i);
        return (
          <text
            key={axis.key}
            x={x}
            y={y}
            fill={COLORS.inkDim}
            fontSize={11}
            fontFamily="Inter, sans-serif"
            textAnchor="middle"
            dominantBaseline="middle"
          >
            {axis.label}
          </text>
        );
      })}
    </svg>
  );
}

function Universe({ fighters, selected, onSelect, width = 760, height = 460 }) {
  const xs = fighters.map((f) => f.pca_x);
  const ys = fighters.map((f) => f.pca_y);
  const pad = 30;
  const xMin = Math.min(...xs), xMax = Math.max(...xs);
  const yMin = Math.min(...ys), yMax = Math.max(...ys);
  const sx = (v) => pad + ((v - xMin) / (xMax - xMin)) * (width - pad * 2);
  const sy = (v) => height - pad - ((v - yMin) / (yMax - yMin)) * (height - pad * 2);

  return (
    <svg width="100%" height={height} viewBox={`0 0 ${width} ${height}`} style={{ display: "block" }}>
      <rect x={0} y={0} width={width} height={height} fill={COLORS.panelAlt} rx={2} />
      {fighters.map((f) => {
        const isSel = selected && selected.name === f.name;
        return (
          <circle
            key={f.name}
            cx={sx(f.pca_x)}
            cy={sy(f.pca_y)}
            r={isSel ? 6.5 : 3.4}
            fill={ARCH_COLORS[f.cluster]}
            fillOpacity={isSel ? 1 : 0.62}
            stroke={isSel ? COLORS.ink : "none"}
            strokeWidth={isSel ? 1.6 : 0}
            style={{ cursor: "pointer" }}
            onClick={() => onSelect(f)}
          >
            <title>{`${f.name} — ${f.archetype}`}</title>
          </circle>
        );
      })}
    </svg>
  );
}

function StatRow({ label, value }) {
  return (
    <div style={{ display: "flex", justifyContent: "space-between", padding: "6px 0", borderBottom: `1px solid ${COLORS.line}` }}>
      <span style={{ color: COLORS.inkFaint, fontSize: 13 }}>{label}</span>
      <span style={{ color: COLORS.ink, fontSize: 13, fontWeight: 600 }}>{value}</span>
    </div>
  );
}

export default function BoxingGenome() {
  const data = FIGHTER_DATA;
  const fighters = data.fighters;
  const [query, setQuery] = useState("");
  const [selected, setSelected] = useState(
    fighters.find((f) => f.name === "Naoya Inoue") || fighters[0]
  );

  const filtered = useMemo(() => {
    if (!query.trim()) return fighters;
    const q = query.toLowerCase();
    return fighters.filter(
      (f) => f.name.toLowerCase().includes(q) || f.division.toLowerCase().includes(q)
    );
  }, [query, fighters]);

  const color = ARCH_COLORS[selected.cluster];

  return (
    <div
      style={{
        background: COLORS.bg,
        minHeight: "100vh",
        fontFamily: "Inter, sans-serif",
        color: COLORS.ink,
        padding: "28px 24px 60px",
      }}
    >
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Bebas+Neue&family=Inter:wght@400;500;600;700&display=swap');
        * { box-sizing: border-box; }
        input:focus, button:focus { outline: 2px solid ${COLORS.brass}; outline-offset: 1px; }
        ::-webkit-scrollbar { width: 8px; }
        ::-webkit-scrollbar-thumb { background: ${COLORS.line}; border-radius: 4px; }
      `}</style>

      {/* Header */}
      <div style={{ maxWidth: 1180, margin: "0 auto 22px" }}>
        <div style={{ display: "flex", alignItems: "baseline", gap: 14, flexWrap: "wrap" }}>
          <h1
            style={{
              fontFamily: "'Bebas Neue', sans-serif",
              fontSize: 44,
              letterSpacing: 1,
              margin: 0,
              color: COLORS.ink,
            }}
          >
            The Boxing Genome
          </h1>
          <span style={{ color: COLORS.inkFaint, fontSize: 14 }}>
            {data.meta.n_fighters} professional fighters, mapped by statistical DNA — not by opinion.
          </span>
        </div>
      </div>

      {/* Archetype legend strip */}
      <div style={{ maxWidth: 1180, margin: "0 auto 22px" }}>
        <div style={{ display: "flex", gap: 0, flexWrap: "wrap", background: COLORS.panel, border: `1px solid ${COLORS.line}` }}>
          {data.archetypes.map((a, i) => (
            <div
              key={a.cluster}
              style={{
                flex: "1 1 200px",
                padding: "14px 16px",
                borderRight: i < data.archetypes.length - 1 ? `1px solid ${COLORS.line}` : "none",
              }}
            >
              <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 6 }}>
                <span style={{ width: 9, height: 9, borderRadius: "50%", background: ARCH_COLORS[a.cluster], display: "inline-block" }} />
                <span style={{ fontWeight: 700, fontSize: 14 }}>{a.name}</span>
                <span style={{ color: COLORS.inkFaint, fontSize: 12, marginLeft: "auto" }}>{a.count}</span>
              </div>
              <p style={{ color: COLORS.inkDim, fontSize: 12, lineHeight: 1.45, margin: 0 }}>{a.blurb}</p>
            </div>
          ))}
        </div>
      </div>

      {/* Main grid */}
      <div style={{ maxWidth: 1180, margin: "0 auto", display: "grid", gridTemplateColumns: "260px 1fr 280px", gap: 18 }}>
        {/* Left: search + list */}
        <div style={{ background: COLORS.panel, border: `1px solid ${COLORS.line}`, padding: 14, display: "flex", flexDirection: "column", minHeight: 520 }}>
          <input
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="Search fighter or division"
            style={{
              background: COLORS.panelAlt,
              border: `1px solid ${COLORS.line}`,
              color: COLORS.ink,
              padding: "8px 10px",
              fontSize: 13,
              marginBottom: 10,
              fontFamily: "Inter, sans-serif",
            }}
          />
          <div style={{ overflowY: "auto", flex: 1 }}>
            {filtered.slice(0, 60).map((f) => (
              <div
                key={f.name}
                onClick={() => setSelected(f)}
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: 8,
                  padding: "7px 4px",
                  cursor: "pointer",
                  background: selected.name === f.name ? COLORS.panelAlt : "transparent",
                  borderLeft: selected.name === f.name ? `3px solid ${COLORS.brass}` : "3px solid transparent",
                }}
              >
                <span style={{ width: 7, height: 7, borderRadius: "50%", background: ARCH_COLORS[f.cluster], flexShrink: 0 }} />
                <div style={{ minWidth: 0 }}>
                  <div style={{ fontSize: 13, fontWeight: selected.name === f.name ? 700 : 500, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>
                    {f.name}
                  </div>
                  <div style={{ fontSize: 11, color: COLORS.inkFaint, textTransform: "capitalize" }}>{f.division}</div>
                </div>
              </div>
            ))}
            {filtered.length === 0 && (
              <p style={{ color: COLORS.inkFaint, fontSize: 13 }}>No fighter matches that search.</p>
            )}
          </div>
        </div>

        {/* Center: tale of the tape + DNA */}
        <div style={{ background: COLORS.panel, border: `1px solid ${COLORS.line}`, padding: 20 }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 6 }}>
            <div>
              <h2 style={{ fontFamily: "'Bebas Neue', sans-serif", fontSize: 32, letterSpacing: 0.5, margin: 0 }}>
                {selected.name}
              </h2>
              <div style={{ color: color, fontSize: 13, fontWeight: 600, marginTop: 2, textTransform: "capitalize" }}>
                {selected.archetype} · {selected.division}
              </div>
            </div>
            <div style={{ textAlign: "right" }}>
              <div style={{ fontSize: 22, fontWeight: 700, color: COLORS.ink }}>
                {selected.win}-{selected.lose}-{selected.draw}
              </div>
              <div style={{ fontSize: 11, color: COLORS.inkFaint }}>record</div>
            </div>
          </div>
          <p style={{ color: COLORS.inkDim, fontSize: 13, lineHeight: 1.5, marginTop: 10, marginBottom: 18, maxWidth: 560 }}>
            {selected.archetype_blurb}
          </p>

          <div style={{ display: "grid", gridTemplateColumns: "260px 1fr", gap: 24 }}>
            <div style={{ display: "flex", justifyContent: "center" }}>
              <DnaRadar fighter={selected} color={color} />
            </div>
            <div>
              <StatRow label="Nationality" value={selected.nationality} />
              <StatRow label="Stance" value={selected.stance} />
              <StatRow label="Age" value={selected.age ?? "—"} />
              <StatRow label="Height / Reach" value={`${selected.height_in}″ / ${selected.reach_in}″`} />
              <StatRow label="Career span" value={selected.career} />
              <StatRow label="KO rate" value={`${selected.ko_pct}%`} />
              <StatRow label="Bouts / rounds" value={`${selected.bouts} / ${selected.rounds}`} />
              <StatRow label="Titles" value={selected.titles || "none listed"} />
            </div>
          </div>
        </div>

        {/* Right: closest matches */}
        <div style={{ background: COLORS.panel, border: `1px solid ${COLORS.line}`, padding: 14 }}>
          <div style={{ fontSize: 13, fontWeight: 700, marginBottom: 10, color: COLORS.ink }}>
            Closest statistical matches
          </div>
          {selected.similar.map((s, i) => {
            const match = fighters.find((f) => f.name === s.name);
            return (
              <div
                key={s.name}
                onClick={() => match && setSelected(match)}
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: 8,
                  padding: "8px 4px",
                  borderBottom: i < selected.similar.length - 1 ? `1px solid ${COLORS.line}` : "none",
                  cursor: "pointer",
                }}
              >
                <span style={{ width: 7, height: 7, borderRadius: "50%", background: ARCH_COLORS[s.cluster], flexShrink: 0 }} />
                <div style={{ minWidth: 0, flex: 1 }}>
                  <div style={{ fontSize: 12.5, fontWeight: 500, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>
                    {s.name}
                  </div>
                  <div style={{ fontSize: 10.5, color: COLORS.inkFaint, textTransform: "capitalize" }}>{s.division}</div>
                </div>
                <div style={{ fontSize: 13, fontWeight: 700, color: COLORS.brass }}>{s.score}%</div>
              </div>
            );
          })}
        </div>
      </div>

      {/* Universe */}
      <div style={{ maxWidth: 1180, margin: "22px auto 0" }}>
        <div style={{ background: COLORS.panel, border: `1px solid ${COLORS.line}`, padding: 18 }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", marginBottom: 12 }}>
            <div style={{ fontSize: 13, fontWeight: 700 }}>The universe</div>
            <div style={{ fontSize: 11.5, color: COLORS.inkFaint }}>
              Two-axis projection of every fighter's DNA — nearby points fight a similar statistical style. Click a point to load it above.
            </div>
          </div>
          <Universe fighters={fighters} selected={selected} onSelect={setSelected} />
        </div>
      </div>

      {/* Footer note */}
      <div style={{ maxWidth: 1180, margin: "18px auto 0" }}>
        <p style={{ color: COLORS.inkFaint, fontSize: 11.5, lineHeight: 1.6 }}>
          Archetypes are discovered by k-means clustering (k=5) over nine engineered features — knockout rate, rounds
          per bout, bouts per year, win rate, career length, age, height, reach, and reach-to-height ratio — then
          named by inspecting what separates each group. Silhouette score ≈ 0.15: the groups are real but soft and
          overlapping, which tracks with boxing having genuine hybrid styles rather than five hard categories. This
          dataset is one row per fighter (career totals), so it cannot show how an individual fighter's style changed
          over time — the "universe" and DNA views are a snapshot, not a trajectory.
        </p>
      </div>
    </div>
  );
}
